	rec := httptest.NewRecorder()
	return e.NewContext(req, rec), rec
}

// assert503 invokes the proxy middleware built from b and asserts a non-panicking 503 HTTPError.
func assert503(t *testing.T, b middleware.ProxyBalancer) {
	t.Helper()
	c, _ := newCtx()
	nextCalled := false
	h := middleware.ProxyWithConfig(middleware.ProxyConfig{Balancer: b})(func(c echo.Context) error {
		nextCalled = true
		return c.String(http.StatusOK, "next")
	})
	err := h(c)
	if nextCalled {
		t.Fatalf("next handler must not be called when balancer has no targets")
	}
	he, ok := err.(*echo.HTTPError)
	if !ok {
		t.Fatalf("expected *echo.HTTPError, got %T (%v)", err, err)
	}
	if he.Code != http.StatusServiceUnavailable {
		t.Fatalf("expected code 503, got %d", he.Code)
	}
	if he != echo.ErrServiceUnavailable {
		t.Fatalf("expected echo.ErrServiceUnavailable identity, got %#v", he)
	}
