func (c *context) Scheme() string {
	// Can't use `r.Request.URL.Scheme`
	// See: https://groups.google.com/forum/#!topic/golang-nuts/pMUkBlQBDF0
	if c.IsTLS() {
		return "https"
	}
	if scheme := c.schemeFromHeader(HeaderXForwardedProto); scheme != "" {
		return scheme
	}
	if scheme := c.schemeFromHeader(HeaderXForwardedProtocol); scheme != "" {
		return scheme
	}
	if ssl := c.request.Header.Get(HeaderXForwardedSsl); ssl == "on" {
		return "https"
	}
	if scheme := c.schemeFromHeader(HeaderXUrlScheme); scheme != "" {
		return scheme
	}
	return "http"
}

// schemeFromHeader returns the scheme from the given header if it is a valid
// scheme ("http" or "https"), otherwise it returns an empty string.
func (c *context) schemeFromHeader(header string) string {
	scheme := c.request.Header.Get(header)
	if scheme == "http" || scheme == "https" {
		return scheme
	}
	return ""
}
```

