package echo

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func mw(name string, log *[]string) MiddlewareFunc {
	return func(next HandlerFunc) HandlerFunc {
		return func(c Context) error {
			*log = append(*log, name)
			c.Response().Header().Add("X-MW", name)
			return next(c)
		}
	}
}

func do(e *Echo, method, path string) *httptest.ResponseRecorder {
	req := httptest.NewRequest(method, path, nil)
	rec := httptest.NewRecorder()
	e.ServeHTTP(rec, req)
	return rec
}

func TestZZReproSamePathSameGroup(t *testing.T) {
	var log []string
	e := New()
	g1 := e.Group("/api")
	g1.Use(mw("m1", &log))
	g1.GET("/users", func(c Context) error { return c.String(200, "h1") })

	g2 := e.Group("/api")
	g2.Use(mw("m2", &log))
	g2.GET("/users", func(c Context) error { return c.String(200, "h2") })

	rec := do(e, http.MethodGet, "/api/users")
	t.Logf("same-path same-group: status=%d body=%q X-MW=%v log=%v", rec.Code, rec.Body.String(), rec.Header().Values("X-MW"), log)
}

