	e := New()
	g1 := e.Group("/api")
	g1.Use(mw("m1", &log))
	g1.GET("/users", func(c Context) error { return c.String(200, "h1") })

	g2 := e.Group("/api")
	g2.Use(mw("m2", &log))
	g2.GET("/items", func(c Context) error { return c.String(200, "h2") })

